package io.github.yuroyami.libmpvkt.canvas

import android.util.Base64
import java.io.File

/**
 * A two second 320x240 H.264 test pattern, carried in the test itself rather than as an asset:
 * the KMP device test source set does not package assets by convention, and a fixture the test
 * cannot open is a failure that looks like a renderer bug.
 *
 * Made with: ffmpeg -f lavfi -i testsrc=duration=2:size=320x240:rate=30 -pix_fmt yuv420p -c:v libx264 -preset veryfast
 */
internal object TestVideo {
    fun writeTo(dir: File): File = File(dir, "testsrc.mp4").also { f ->
        if (!f.exists() || f.length().toInt() != Base64.decode(BASE64, Base64.DEFAULT).size) {
            f.writeBytes(Base64.decode(BASE64, Base64.DEFAULT))
        }
    }

